def graph(nt):
 if not nt:return None
 nodes=[]
 for n in nt.nodes:
  d={'name':n.name,'type':n.bl_idname,'label':n.label,'inputs':[],'outputs':[],'properties':{}}
  for prop in ['operation','blend_type','interpolation','data_type','clamp_type','vector_type','gradient_type','distribution','invert','use_clamp']:
   if hasattr(n,prop):d['properties'][prop]=val(getattr(n,prop))
  for k in ['inputs','outputs']:
   for i,sk in enumerate(getattr(n,k)):
    e={'index':i,'name':sk.name,'identifier':sk.identifier}
    if hasattr(sk,'default_value'):e['default']=val(sk.default_value)
    d[k].append(e)
  if hasattr(n,'color_ramp'):d['ramp']={'interpolation':n.color_ramp.interpolation,'mode':n.color_ramp.color_mode,'elements':[[x.position,list(x.color)] for x in n.color_ramp.elements]}
  if n.type=='TEX_COORD':d['object']=n.object.name if n.object else None
  if n.type=='TEX_IMAGE':d['image']=n.image.name if n.image else None
  nodes.append(d)
